mappings.INQUIRY.response:
status = 200 and body.res.state = "OPEN" and $type(body.res.amt) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.res.acct,
     "attributes": {"amount": body.res.amt, "dueDate": body.res.due, "billPeriod": body.res.month}}
: status = 200 and body.res.state = "DONE"
  ? {"outcome": "FAILED", "code": "X02", "message": "Bill already paid"}
: (status = 422 or status = 404) and $type(body.res.err) = "string" and body.res.err != ""
  ? {"outcome": "FAILED", "code": body.res.err, "message": body.res.msg}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.PAY.response:
status = 200 or status = 202
  ? (body.res.state = "DONE" and $type(body.res.rcpt) = "string" and body.res.rcpt != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.res.rcpt}
    : body.res.state = "WAIT"
      ? {"outcome": "PENDING", "partnerRef": body.res.rcpt}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.res.err) = "string" and body.res.err != ""
  ? {"outcome": "FAILED", "code": body.res.err, "message": body.res.msg}
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400"}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.res.state = "DONE" and $type(body.res.rcpt) = "string" and body.res.rcpt != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.res.rcpt}
    : body.res.state = "WAIT"
      ? {"outcome": "PENDING", "partnerRef": body.res.rcpt}
    : body.res.state = "FAIL" and $type(body.res.err) = "string"
      ? {"outcome": "FAILED", "code": body.res.err, "message": body.res.msg}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.res.state = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.res.err}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.res.state = "VOID" and $type(body.res.rev_rcpt) = "string" and body.res.rev_rcpt != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.res.rev_rcpt}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.res.err) = "string" and body.res.err != ""
  ? {"outcome": "FAILED", "code": body.res.err, "message": body.res.msg}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.CALLBACK.response:
$type(body.ref) != "string" or body.ref = "" ? {}
: body.state = "DONE" and $type(body.rcpt) = "string" and body.rcpt != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.rcpt, "reference": body.ref}
: body.state = "FAIL" and $type(body.err) = "string" and body.err != ""
  ? {"outcome": "FAILED", "partnerRef": body.rcpt, "reference": body.ref,
     "code": body.err, "message": body.msg}
: {}
